package search

import (
	"strings"

	"github.com/yuin/goldmark"
	"github.com/yuin/goldmark/ast"
	"github.com/yuin/goldmark/extension"
	"github.com/yuin/goldmark/parser"
	"github.com/yuin/goldmark/text"
)

// Section keeps heading IDs generated by the same parser as the reader.
type Section struct {
	Title   string
	Heading string
	Level   int
	Anchor  string
	Body    string
}

func extractSections(source []byte) []Section {
	source = headingFrontmatter.ReplaceAll(source, nil)
	md := goldmark.New(goldmark.WithExtensions(extension.GFM, extension.Footnote, extension.DefinitionList),
		goldmark.WithParserOptions(parser.WithAutoHeadingID(), parser.WithAttribute()))
	root := md.Parser().Parse(text.NewReader(source))
	sections := []Section{{}}
	var headings [6]string
	var body strings.Builder
	flush := func() {
		sections[len(sections)-1].Body = strings.Join(strings.Fields(body.String()), " ")
		body.Reset()
	}
	_ = ast.Walk(root, func(node ast.Node, entering bool) (ast.WalkStatus, error) {
		if !entering {
			return ast.WalkContinue, nil
		}
		if heading, ok := node.(*ast.Heading); ok {
			flush()
			headings[heading.Level-1] = string(heading.Text(source))
			for i := heading.Level; i < len(headings); i++ {
				headings[i] = ""
			}
			var trail []string
			for _, label := range headings {
				if label != "" {
					trail = append(trail, label)
				}
			}
			anchor, _ := heading.AttributeString("id")
			id, _ := anchor.([]byte)
			sections = append(sections, Section{Title: strings.Join(trail, " / "), Heading: string(heading.Text(source)), Level: heading.Level, Anchor: string(id)})
			return ast.WalkSkipChildren, nil
		}
		switch n := node.(type) {
		case *ast.Text:
			body.Write(n.Value(source))
			body.WriteByte(' ')
		case *ast.String:
			body.Write(n.Value)
			body.WriteByte(' ')
		case *ast.FencedCodeBlock, *ast.CodeBlock:
			lines := node.Lines()
			for i := 0; i < lines.Len(); i++ {
				line := lines.At(i)
				body.Write(line.Value(source))
			}
			body.WriteByte(' ')
			return ast.WalkSkipChildren, nil
		}
		return ast.WalkContinue, nil
	})
	flush()
	return sections
}

func bestSection(doc Document, terms []string) Section {
	best := Section{Body: doc.Body}
	bestScore := 0
	for _, section := range doc.Sections {
		if section.Body == "" {
			continue
		}
		score := 0
		title, heading, body := fold(section.Title), fold(section.Heading), fold(section.Body)
		for _, term := range terms {
			if strings.Contains(title, term) {
				score++
			}
			if strings.Contains(heading, term) {
				score += 5
			}
			if strings.Contains(body, term) {
				score += 2
			}
		}
		if score > bestScore {
			best, bestScore = section, score
		}
	}
	if best.Body == "" {
		best.Body = best.Title
	}
	return best
}
